package com.examservice.domain.model;import java.time.Instant;import java.util.*;public record Exam(UUID id,String name,String examCode,int durationMinutes,ExamStatus status,String facultyId,UUID subjectId,UUID matrixId,UUID templateId,UUID createdBy,List<ExamVersion>versions,Instant createdAt,Instant updatedAt){public Exam{if(name==null||name.isBlank())throw new IllegalArgumentException("Exam name is required");if(examCode==null||examCode.isBlank())throw new IllegalArgumentException("Exam code is required");if(durationMinutes<1||durationMinutes>600)throw new IllegalArgumentException("Exam duration must be between 1 and 600 minutes");Objects.requireNonNull(status);versions=List.copyOf(versions);}}
